-- 026: Lesson check-in cards (lesson tutor redesign, slice 3 — 2026-10-13).
-- A short recap of the slides since the previous check-in, shown at the
-- lesson player's checkpoint positions (every 4th slide). Pre-generated by
-- ai-service/scripts/generate_checkins.py, so a view costs no model call.
-- after_slide is the slide_number of the last slide the recap covers; the
-- card is shown on arrival at the slide after it. Replay-safe.
CREATE TABLE IF NOT EXISTS lesson_checkins (
  id              SERIAL PRIMARY KEY,
  lesson_code     VARCHAR(20) NOT NULL,
  after_slide     INTEGER NOT NULL,
  from_slide      INTEGER NOT NULL,
  recap_points    JSONB NOT NULL CHECK (jsonb_typeof(recap_points) = 'array' AND jsonb_array_length(recap_points) BETWEEN 2 AND 6),
  exercise_prompt TEXT NOT NULL,
  model           TEXT NOT NULL,
  generated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  reviewed_at     TIMESTAMPTZ,
  flagged_count   INTEGER NOT NULL DEFAULT 0,
  UNIQUE (lesson_code, after_slide)
);
CREATE INDEX IF NOT EXISTS idx_lesson_checkins_lesson ON lesson_checkins (lesson_code, after_slide);
